<?php
namespace App\Http\Requests\Releases\Fuel;
use Illuminate\Foundation\Http\FormRequest;
class FuelRefuelingRequest extends FormRequest { public function authorize(): bool{return true;} public function rules(): array{return ['fuel_station_id'=>'required|integer|exists:fuel_stations,id','product_id'=>'required|integer|exists:products,id','fleet_id'=>'required|integer|exists:fleets,id','operator_id'=>'nullable|integer|exists:agricultural_operators,id','fuel_registradora_id'=>'nullable|integer|exists:fuel_registradoras,id','refueled_at'=>'required|date','quantity'=>'required|numeric|gt:0','unit_price'=>'nullable|numeric|min:0','total_value'=>'nullable|numeric|min:0','marking_type'=>'required|string|size:1|in:H,K','meter_value'=>'required|numeric|min:0','observation'=>'nullable|string|max:500'];} }
